import os
import tempfile
import tomllib
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load


def _make_env(prefix: str, **kwargs) -> dict:
    env = os.environ.copy()
    for k, v in kwargs.items():
        env[f"{prefix.upper()}__{k.upper()}"] = str(v)
    return env


def _write_toml(path: Path, data: dict) -> None:
    with open(path, "wb") as f:
        tomllib.dump(data, f)


def test_defaults_only():
    cfg = load({"a": 1, "b": "hello"})
    assert cfg == {"a": 1, "b": "hello"}


def test_toml_over_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = Path(f.name)
        _write_toml(path, {"a": 2, "c": 3})
    try:
        cfg = load({"a": 1, "b": "hello"}, toml_path=str(path))
        assert cfg == {"a": 2, "b": "hello", "c": 3}
    finally:
        path.unlink()


def test_env_over_defaults():
    cfg = load({"a": 1, "b": "hello"}, env=_make_env("APP", a=99))
    assert cfg == {"a": 99, "b": "hello"}


def test_env_over_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = Path(f.name)
        _write_toml(path, {"a": 2})
    try:
        cfg = load({"a": 1}, toml_path=str(path), env=_make_env("APP", a=99))
        assert cfg == {"a": 99}
    finally:
        path.unlink()


def test_nested_defaults():
    cfg = load({"server": {"port": 8080}})
    assert cfg == {"server": {"port": 8080}}


def test_nested_toml():
