def _dict_to_toml(data: dict) -> str:
    """Convert a nested dict to a TOML string."""
    lines = []
    for key, value in data.items():
        if isinstance(value, dict):
            lines.append(f"[{key}]")
            lines.append(_dict_to_toml(value))
        else:
            lines.append(f"{key} = {value}")
    return "\n".join(lines)

def _write_toml(path: str, data: dict) -> None:
    """Write a TOML file."""
    with open(path, "w") as f:
        f.write(_dict_to_toml(data))

